configuration.source:
def configuration(cfg,slot):
    from .carrier_c1_data import C1_A
    if slot not in PREFIXES:raise ValueError('NOT_PRESENT_SLOT_FORBIDDEN:'+slot)
    projection={k:cfg.get(k) for k in ('geometry_connector','geometry_online','carrier_placement','frame_embeddings')}
    if slot=='heads_gf1_connector':
        absent=projection['geometry_connector']=='none' and not projection['geometry_online']
    else:
        absent=projection['carrier_placement']==C1_A and not projection['frame_embeddings']
    if not absent:raise ValueError('NOT_PRESENT_CONFIG_NAMES_COMPONENT:'+slot)
    return projection

evidence.source:
def evidence(cfg,artifact):
    """The persisted export pins the actual head payload; absence is never asserted from a list alone."""
    import torch
    codes=cfg.get('r1_training',{}).get('not_present_slots',[])
    if not codes:return {}
    if not isinstance(codes,list) or set(codes)!=set(SLOT_CODES) or len(codes)!=2:raise ValueError('NOT_PRESENT_SLOT_FORBIDDEN')
    slots=[SLOT_CODES[code] for code in codes]
    for slot in slots:configuration(cfg,slot)
    pin=artifact.get('heads')
    if not pin:raise ValueError('NOT_PRESENT_STATE_INVENTORY_REQUIRED')
    state=torch.load(pinned(pin),map_location='meta',weights_only=True)
    if not isinstance(state,dict):raise ValueError('NOT_PRESENT_STATE_INVENTORY_INVALID')
    model=build(cfg)
    return {slot:prove(cfg,model,state,slot,pin) for slot in slots}

prove.source:
def prove(cfg,model,state,slot,inventory_pin):
    """Require a native-built module inventory and an authenticated state inventory."""
    from .carrier_c1 import CarrierC1
    import torch
    projection=configuration(cfg,slot)
    if not isinstance(model,CarrierC1):raise ValueError('NOT_PRESENT_NATIVE_BUILDER_REQUIRED')
    if (model.carrier_placement!=cfg['carrier_placement'] or model.geometry_online!=cfg.get('geometry_online')):
        raise ValueError('NOT_PRESENT_BUILDER_CONFIG_DIFFERS')
    modules=sorted(name for name,_ in model.named_modules())
    if any(matches(name,slot) for name in modules):raise ValueError('NOT_PRESENT_BUILT_MODULE:'+slot)
    tensors=sorted(name for name,value in state.items() if isinstance(value,torch.Tensor))
    if any(matches(name,slot) for name in tensors):raise ValueError('NOT_PRESENT_STATE_TENSOR:'+slot)
    import inspect
    builder=file_pin(inspect.getsourcefile(CarrierC1))
    return dict(status='NOT_PRESENT',record=dict(schema='r1-component-absence-v1',slot=slot,
        configuration=projection,builder=builder,entry='CarrierC1.__init__',modules=modules,
        inventory=inventory_pin,tensors=tensors,prefixes=list(PREFIXES[slot]),matching_tensors=0))

artifact_binding.source:
def artifact_binding(cfg, status):
    """Carry the pinned preparation that actually recorded these statuses."""
    if not status:
        return {}
    if 'r1_training' in cfg:
        pin = cfg.get('preparation')
    else:
        from .r1_handover import metadata_load
        parent = metadata_load(cfg['init_artifact']['artifact'], {})
        pin = parent.get('component_preparation')
    if not pin or normalize(load(pinned(pin)).get('component_evidence', {})) != status:
        raise ValueError('COMPONENT_EVIDENCE_PREPARATION_MISMATCH:export')
    return dict(component_preparation=pin, component_evidence_sha256=digest(status))

artifact_status.source:
def artifact_status(cfg):
    """Publish status on every N export and preserve inherited deferred slots."""
    from .r1_handover import metadata_load
    spec = (cfg.get('init_artifact') or {}).get('artifact')
    inherited = metadata_load(spec, (cfg.get('r1_training') or {}).get('persisted_files', {})).get('component_evidence', {}) if spec else {}
    if 'r1_training' in cfg:
        from .r1_training import training_components
        records = training_components(cfg['r1_training']['registry'], cfg)
        inherited = {**normalize(records), **inherited}
        inherited.update({k:v for k,v in records.items() if v.get('status')=='NOT_PRESENT'})
    if cfg.get('r2_evaluation'):
        guard(dict(component_evidence=inherited, component_preparation=cfg.get('preparation'),
                   component_evidence_sha256=digest(inherited)),
              ['VSI-Bench', 'VSTI', 'ReVSI'], 'official-export')
    return inherited

normalize.source:
def normalize(records):
    return {k: v if v.get('status') in ('DEFERRED', 'VERIFIED','NOT_PRESENT') else dict(status='VERIFIED', record=v)
            for k, v in records.items()}

training_components.source:
def training_components(registry_pin, cfg, root=None):
    """Keep the complete registry; only an absent fusion connector is out of scope."""
    from .r2_policy import slots, record, CHOICES
    from .r2_portable import bound
    registry = load(bound(registry_pin, root))
    expected = slots()
    if set(registry) != set(expected):
        raise ValueError('Component registry differs')
    if cfg.get('geometry_connector') != 'none' or cfg.get('geometry_online'):
        raise ValueError('R1_FUSION_REFUSED')
    from .r1_components import deferred
    pending = deferred(cfg, root=root)
    result = {}
    for name, spec in expected.items():
        entry = registry[name]
        if any(entry.get(k) != spec[k] for k in ('component', 'component_class', 'phase', 'expected_schema')):
            raise ValueError('Component slot was reclassified')
        if pending is not None and name in pending:
            result[name] = pending[name]
            continue
        if name in CHOICES or name == 'heads_gf1_connector':
            continue
        result[name] = record(entry, root)
    return result
